PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS studio_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT,password_hash TEXT,auth_status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at TEXT,last_seen_at TEXT);
CREATE TABLE IF NOT EXISTS studio_admin_members(user_id TEXT PRIMARY KEY REFERENCES studio_users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('primary_admin','admin','editor')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at TEXT,last_seen_at TEXT);
CREATE TABLE IF NOT EXISTS studio_auth_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES studio_users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,last_seen_at TEXT,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS studio_collaborator_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,display_name TEXT,email TEXT,role TEXT,signed_in_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,signed_out_at TEXT);
CREATE TABLE IF NOT EXISTS studio_world_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,record_type TEXT NOT NULL,name TEXT NOT NULL,subtype TEXT,description TEXT,emblem_url TEXT,cover_url TEXT,lore_details TEXT NOT NULL DEFAULT '{}',workflow_status TEXT NOT NULL DEFAULT 'draft',is_public INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_world_relations(id TEXT PRIMARY KEY,source_record_id TEXT NOT NULL REFERENCES studio_world_records(id) ON DELETE CASCADE,target_record_id TEXT NOT NULL REFERENCES studio_world_records(id) ON DELETE CASCADE,relation_label TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(source_record_id,target_record_id,relation_label));
CREATE TABLE IF NOT EXISTS studio_characters(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',workflow_status TEXT NOT NULL DEFAULT 'draft',identity TEXT NOT NULL DEFAULT '{}',appearance TEXT NOT NULL DEFAULT '{}',origin_lore TEXT NOT NULL DEFAULT '{}',abilities TEXT NOT NULL DEFAULT '{}',relationships TEXT NOT NULL DEFAULT '{}',media TEXT NOT NULL DEFAULT '{}',portrait_url TEXT,current_step INTEGER NOT NULL DEFAULT 1,is_complete INTEGER NOT NULL DEFAULT 0,is_public INTEGER NOT NULL DEFAULT 0,realm_record_id TEXT REFERENCES studio_world_records(id) ON DELETE SET NULL,race_record_id TEXT REFERENCES studio_world_records(id) ON DELETE SET NULL,faction_record_id TEXT REFERENCES studio_world_records(id) ON DELETE SET NULL,family_record_id TEXT REFERENCES studio_world_records(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_character_relationships(id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL,source_character_id TEXT NOT NULL REFERENCES studio_characters(id) ON DELETE CASCADE,target_character_id TEXT NOT NULL REFERENCES studio_characters(id) ON DELETE CASCADE,relationship_type TEXT NOT NULL,relationship_source TEXT NOT NULL DEFAULT 'manual',manual_override INTEGER NOT NULL DEFAULT 0,is_locked INTEGER NOT NULL DEFAULT 0,is_deleted INTEGER NOT NULL DEFAULT 0,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(source_character_id<>target_character_id),UNIQUE(source_character_id,target_character_id,relationship_type));
CREATE TABLE IF NOT EXISTS studio_family_tree_layouts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,center_character_id TEXT NOT NULL REFERENCES studio_characters(id) ON DELETE CASCADE,positions TEXT NOT NULL DEFAULT '{}',hidden_ids TEXT NOT NULL DEFAULT '[]',locked_ids TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,center_character_id));
CREATE TABLE IF NOT EXISTS studio_world_locations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,location_type TEXT NOT NULL DEFAULT 'other',description TEXT,parent_location_id TEXT REFERENCES studio_world_locations(id) ON DELETE SET NULL,codex_record_id TEXT REFERENCES studio_world_records(id) ON DELETE SET NULL,map_x REAL,map_y REAL,image_url TEXT,tags TEXT NOT NULL DEFAULT '[]',workflow_status TEXT NOT NULL DEFAULT 'draft',is_public INTEGER NOT NULL DEFAULT 0,archived_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_timeline_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,title TEXT NOT NULL,era TEXT,display_date TEXT,sort_order INTEGER NOT NULL DEFAULT 0,description TEXT,location_id TEXT REFERENCES studio_world_locations(id) ON DELETE SET NULL,codex_record_id TEXT REFERENCES studio_world_records(id) ON DELETE SET NULL,character_id TEXT REFERENCES studio_characters(id) ON DELETE SET NULL,image_url TEXT,tags TEXT NOT NULL DEFAULT '[]',workflow_status TEXT NOT NULL DEFAULT 'draft',is_public INTEGER NOT NULL DEFAULT 0,archived_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_world_atlas(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,title TEXT NOT NULL,map_url TEXT,description TEXT,is_public INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_favorites(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS studio_record_types(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,description TEXT,icon TEXT,is_system INTEGER NOT NULL DEFAULT 0,created_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_database_records(id TEXT PRIMARY KEY,created_by TEXT NOT NULL,updated_by TEXT,record_type_id TEXT NOT NULL REFERENCES studio_record_types(id),record_code TEXT UNIQUE,name TEXT NOT NULL,subtitle TEXT,summary TEXT,details TEXT NOT NULL DEFAULT '{}',image_url TEXT,notes TEXT,last_reviewed_at TEXT,workflow_status TEXT NOT NULL DEFAULT 'draft',canon_status TEXT NOT NULL DEFAULT 'draft',canon_notes TEXT,is_public INTEGER NOT NULL DEFAULT 0,public_slug TEXT UNIQUE,canon_updated_at TEXT,archived_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_collections(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_collection_items(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL REFERENCES studio_collections(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(collection_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS studio_tags(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,created_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_tag_assignments(id TEXT PRIMARY KEY,tag_id TEXT NOT NULL REFERENCES studio_tags(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tag_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS studio_universal_links(id TEXT PRIMARY KEY,source_type TEXT NOT NULL,source_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,relation_label TEXT NOT NULL,notes TEXT,created_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_media_assets(id TEXT PRIMARY KEY,uploaded_by TEXT NOT NULL,title TEXT NOT NULL,asset_url TEXT NOT NULL,local_path TEXT,media_type TEXT NOT NULL,caption TEXT,credit TEXT,alt_text TEXT,tags TEXT NOT NULL DEFAULT '[]',sync_state TEXT NOT NULL DEFAULT 'metadata_only',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_media_attachments(id TEXT PRIMARY KEY,media_id TEXT NOT NULL REFERENCES studio_media_assets(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,caption_override TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(media_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS studio_record_references(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES studio_database_records(id) ON DELETE CASCADE,label TEXT NOT NULL,reference_type TEXT NOT NULL,url TEXT,citation TEXT,notes TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_field_templates(id TEXT PRIMARY KEY,record_type_id TEXT NOT NULL REFERENCES studio_record_types(id) ON DELETE CASCADE,name TEXT NOT NULL,fields TEXT NOT NULL DEFAULT '[]',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_database_locks(record_id TEXT PRIMARY KEY REFERENCES studio_database_records(id) ON DELETE CASCADE,locked_by TEXT NOT NULL,locked_by_email TEXT,locked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS studio_database_revisions(id TEXT PRIMARY KEY,record_id TEXT NOT NULL,record_code TEXT,record_name TEXT,changed_by TEXT,changed_by_email TEXT,snapshot TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_backup_snapshots(id TEXT PRIMARY KEY,created_by TEXT NOT NULL,label TEXT NOT NULL,snapshot TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_canon_history(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,entity_label TEXT,previous_status TEXT,new_status TEXT NOT NULL,reason TEXT,changed_by TEXT,changed_by_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_continuity_issues(id TEXT PRIMARY KEY,issue_type TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'warning',entity_type TEXT NOT NULL,entity_id TEXT,entity_label TEXT,message TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_public_settings(id INTEGER PRIMARY KEY CHECK(id=1),title TEXT NOT NULL DEFAULT 'The Umbral World',subtitle TEXT,introduction TEXT,hero_image_url TEXT,is_enabled INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_story_projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,project_type TEXT NOT NULL DEFAULT 'story',summary TEXT,status TEXT NOT NULL DEFAULT 'planning',canon_status TEXT NOT NULL DEFAULT 'draft',spoiler_level TEXT NOT NULL DEFAULT 'none',is_public INTEGER NOT NULL DEFAULT 0,cover_url TEXT,created_by TEXT,updated_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_story_arcs(id TEXT PRIMARY KEY,project_id TEXT REFERENCES studio_story_projects(id) ON DELETE CASCADE,title TEXT NOT NULL,arc_code TEXT,summary TEXT,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'planned',canon_status TEXT NOT NULL DEFAULT 'draft',spoiler_level TEXT NOT NULL DEFAULT 'none',created_by TEXT,updated_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_story_scenes(id TEXT PRIMARY KEY,project_id TEXT REFERENCES studio_story_projects(id) ON DELETE CASCADE,arc_id TEXT REFERENCES studio_story_arcs(id) ON DELETE SET NULL,title TEXT NOT NULL,scene_code TEXT,summary TEXT,body_notes TEXT,pov_character_id TEXT REFERENCES studio_characters(id) ON DELETE SET NULL,location_id TEXT REFERENCES studio_world_locations(id) ON DELETE SET NULL,timeline_event_id TEXT REFERENCES studio_timeline_events(id) ON DELETE SET NULL,era TEXT,story_date TEXT,sort_order INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'idea',spoiler_level TEXT NOT NULL DEFAULT 'none',created_by TEXT,updated_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_story_beats(id TEXT PRIMARY KEY,project_id TEXT REFERENCES studio_story_projects(id) ON DELETE CASCADE,arc_id TEXT REFERENCES studio_story_arcs(id) ON DELETE SET NULL,scene_id TEXT REFERENCES studio_story_scenes(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT,beat_type TEXT NOT NULL DEFAULT 'plot',status TEXT NOT NULL DEFAULT 'idea',sort_order INTEGER NOT NULL DEFAULT 0,created_by TEXT,updated_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_story_entity_links(id TEXT PRIMARY KEY,story_entity_type TEXT NOT NULL,story_entity_id TEXT NOT NULL,linked_entity_type TEXT NOT NULL,linked_entity_id TEXT NOT NULL,relation_label TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_review_comments(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_by TEXT,created_by_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS studio_assignments(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT,entity_type TEXT,entity_id TEXT,assigned_to TEXT NOT NULL,assigned_by TEXT,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'open',due_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_notifications(id TEXT PRIMARY KEY,recipient_user_id TEXT NOT NULL,actor_user_id TEXT,actor_name TEXT,notification_type TEXT NOT NULL,title TEXT NOT NULL,message TEXT,entity_type TEXT,entity_id TEXT,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_direct_messages(id TEXT PRIMARY KEY,sender_user_id TEXT NOT NULL,recipient_user_id TEXT NOT NULL,body TEXT NOT NULL,entity_type TEXT,entity_id TEXT,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_character_journey(id TEXT PRIMARY KEY,character_id TEXT NOT NULL REFERENCES studio_characters(id) ON DELETE CASCADE,project_id TEXT REFERENCES studio_story_projects(id) ON DELETE CASCADE,arc_id TEXT REFERENCES studio_story_arcs(id) ON DELETE SET NULL,scene_id TEXT REFERENCES studio_story_scenes(id) ON DELETE SET NULL,journey_type TEXT NOT NULL DEFAULT 'development',title TEXT NOT NULL,description TEXT,before_value TEXT,after_value TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_activity_log(id TEXT PRIMARY KEY,actor_user_id TEXT,actor_email TEXT,actor_name TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,entity_label TEXT,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_revisions(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,entity_label TEXT,changed_by TEXT,changed_by_email TEXT,snapshot TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_admin_notes(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,note TEXT NOT NULL,created_by TEXT NOT NULL,created_by_email TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_settings(id INTEGER PRIMARY KEY CHECK(id=1),studio_name TEXT NOT NULL DEFAULT 'Umbra Studio',studio_subtitle TEXT,default_canon_status TEXT NOT NULL DEFAULT 'draft',default_spoiler_level TEXT NOT NULL DEFAULT 'none',autosave_enabled INTEGER NOT NULL DEFAULT 1,autosave_seconds INTEGER NOT NULL DEFAULT 20,stale_session_minutes INTEGER NOT NULL DEFAULT 30,show_dashboard_activity INTEGER NOT NULL DEFAULT 1,show_help_descriptions INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_sync_changes(id TEXT PRIMARY KEY,device_id TEXT NOT NULL,user_id TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,operation TEXT NOT NULL,payload TEXT,base_updated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,applied_at TEXT);
CREATE TABLE IF NOT EXISTS studio_sync_devices(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,device_name TEXT,last_pull_at TEXT,last_push_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO studio_settings(id) VALUES(1);
INSERT OR IGNORE INTO studio_public_settings(id) VALUES(1);
CREATE INDEX IF NOT EXISTS idx_characters_name ON studio_characters(name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS idx_relationship_source ON studio_character_relationships(source_character_id);
CREATE INDEX IF NOT EXISTS idx_relationship_target ON studio_character_relationships(target_character_id);
CREATE INDEX IF NOT EXISTS idx_world_records_type_name ON studio_world_records(record_type,name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS idx_database_records_updated ON studio_database_records(updated_at);
CREATE INDEX IF NOT EXISTS idx_notifications_user_read ON studio_notifications(recipient_user_id,is_read,created_at);
CREATE INDEX IF NOT EXISTS idx_messages_recipient ON studio_direct_messages(recipient_user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_sync_pending ON studio_sync_changes(applied_at,created_at);
